package com.onrender.smartnf.health;
import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class AutoCollectionTests {
 static int count;static void ok(boolean b,String m){if(!b)throw new AssertionError(m);count++;}static void fails(Runnable r,int status){try{r.run();throw new AssertionError("expected failure");}catch(HealthException e){ok(e.status()==status,"status "+status);}}
 static ProductCollectionJobs.View await(ProductCollectionJobs jobs,long member,UUID id)throws Exception{long until=System.currentTimeMillis()+4000;while(System.currentTimeMillis()<until){var v=jobs.get(member,id);if(!Set.of("QUEUED","RUNNING").contains(v.state()))return v;Thread.sleep(10);}throw new AssertionError("job timeout");}
 public static void main(String[] args)throws Exception {
  String allow="User-agent: *\nAllow: /\n";
  ok(HomeplusFlyerCollector.robotsAllow(allow),"explicit wildcard allow");ok(!HomeplusFlyerCollector.robotsAllow("<html>error</html>"),"HTML robots blocked");ok(!HomeplusFlyerCollector.robotsAllow("User-agent: *\nDisallow: /"),"deny all blocked");ok(!HomeplusFlyerCollector.robotsAllow("User-agent: Googlebot\nAllow: /"),"do not impersonate bots");ok(!HomeplusFlyerCollector.robotsAllow(allow+"Disallow: /leaflet"),"leaflet deny");
  ok(HomeplusFlyerCollector.normalize("양파 삼킬로그램 사천구백구십원").equals("양파 3kg 4990원"),"Korean numbers");
  String html=Files.readString(Path.of(args[0]));var actual=HomeplusFlyerCollector.parse(html,"양파",Instant.now().toString());ok(actual.size()==1,"real official page onion row");var onion=actual.getFirst();ok(onion.grams().intValue()==3000&&onion.price().intValue()==4990,"real page pack and member price");ok(onion.branch().equals("금천점")&&!onion.confirmed(),"branch plus review required");ok(onion.validTo().equals("2026-11-18"),"flyer expiry");
  var salmon=HomeplusFlyerCollector.parse(html,"생연어",Instant.now().toString());ok(!salmon.isEmpty()&&salmon.getFirst().grams()==null&&salmon.getFirst().validTo().isEmpty(),"per100g and item dates not guessed");
  ok(HomeplusFlyerCollector.parse(html,"없는품목ZZZ",Instant.now().toString()).isEmpty(),"no invented matches");
  AtomicInteger fetched=new AtomicInteger();var gated=new HomeplusFlyerCollector(false,uri->{fetched.incrementAndGet();return new HomeplusFlyerCollector.Fetch(200,html);});try{gated.collect("양파");throw new AssertionError();}catch(HomeplusFlyerCollector.Unavailable e){ok(e.state.equals("NEEDS_CONFIGURATION")&&fetched.get()==0,"no outbound before configuration");}
  var blocked=new HomeplusFlyerCollector(true,uri->{fetched.incrementAndGet();return new HomeplusFlyerCollector.Fetch(400,"");});try{blocked.collect("양파");throw new AssertionError();}catch(HomeplusFlyerCollector.Unavailable e){ok(e.state.equals("POLICY_UNAVAILABLE")&&fetched.get()==1,"robots HTTP400 prevents flyer fetch");}
  var allowed=new HomeplusFlyerCollector(true,uri->new HomeplusFlyerCollector.Fetch(200,uri.getPath().equals("/robots.txt")?allow:html));ok(allowed.collect("양파").size()==1,"fixed transport pipeline");
  AtomicInteger calls=new AtomicInteger();var api=new IngredientProductService(){@Override public Result search(String q){calls.incrementAndGet();return new Result("11ST",List.of(new Product("123","양파 1kg","농장",java.math.BigDecimal.valueOf(3000),java.math.BigDecimal.valueOf(1000),"https://www.11st.co.kr/products/123","배송 확인",Instant.now().toString())),"ok");}};
  try(var jobs=new ProductCollectionJobs(api,gated)){
   UUID id=UUID.randomUUID();var request=new ProductCollectionJobs.Start(id,"11ST","양파");jobs.start(1,request);var done=await(jobs,1,id);ok(done.state().equals("REVIEW_REQUIRED")&&!done.offers().getFirst().confirmed(),"API drafts only");jobs.start(1,request);ok(calls.get()==1,"same request not rerun");fails(()->jobs.start(1,new ProductCollectionJobs.Start(id,"11ST","감자")),409);fails(()->jobs.get(2,id),404);fails(()->jobs.start(2,request),404);fails(()->jobs.start(1,new ProductCollectionJobs.Start(UUID.randomUUID(),"11ST","양파")),429);fails(()->jobs.start(2,new ProductCollectionJobs.Start(UUID.randomUUID(),"EVIL","양파")),400);ok(jobs.current(2)==null,"current job isolated");
   var h=jobs.start(2,new ProductCollectionJobs.Start(UUID.randomUUID(),"HOMEPLUS","양파"));ok(await(jobs,2,h.id()).state().equals("NEEDS_CONFIGURATION"),"configuration state returned");
   var controller=new ProductCollectionController(new CurrentHealthMember(),jobs);fails(()->controller.start(null,request),401);fails(()->controller.current(null),401);
  }
  var missing=new IngredientProductService(){@Override public Result search(String q){return new Result("11ST",List.of(),"API 키가 설정되지 않았습니다.");}};try(var jobs=new ProductCollectionJobs(missing,gated)){var job=jobs.start(1,new ProductCollectionJobs.Start(UUID.randomUUID(),"11ST","양파"));ok(await(jobs,1,job.id()).state().equals("NEEDS_CONFIGURATION"),"API missing key not fake success");}
  CountDownLatch release=new CountDownLatch(1),started=new CountDownLatch(2);var slow=new IngredientProductService(){@Override public Result search(String q){started.countDown();try{release.await(3,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}return new Result("11ST",List.of(),"empty");}};
  try(var jobs=new ProductCollectionJobs(slow,gated)){for(int i=1;i<=2;i++)jobs.start(i,new ProductCollectionJobs.Start(UUID.randomUUID(),"11ST","양파"));ok(started.await(1,TimeUnit.SECONDS),"two bounded workers");for(int i=3;i<=12;i++)jobs.start(i,new ProductCollectionJobs.Start(UUID.randomUUID(),"11ST","양파"));fails(()->jobs.start(13,new ProductCollectionJobs.Start(UUID.randomUUID(),"11ST","양파")),429);release.countDown();}
  System.out.println("PASS "+count+" auto collection parsing, policy, job lifecycle, isolation and queue checks");
 }
}
